window.__code__["code-w11-mcp-server-server-py"] = {"code_id": "code-w11-mcp-server-server-py", "kind": "local", "title": "server.py", "source_path": "/Users/zhongyou/Desktop/2027年/code/w11/mcp_server/server.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># code/w11/mcp_server/server.py</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-com\"># W11 作业1:自建企业级 MCP Server(毕业项目核心)</span></span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\"><span class=\"c-com\"># 要素:工具注册 + schema(装饰器自动) + 鉴权(token) + 超时 + 审计 + 危险拦截</span></span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\"><span class=\"c-com\"># 对照 QwenPaw app/routers/mcp.py 的策略/白名单/审计(本文件是其简化骨架)</span></span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\"><span class=\"c-com\"># 前置: uv pip install mcp</span></span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\"><span class=\"c-com\"># 运行:  python code/w11/mcp_server/server.py  (作为 stdio MCP server 运行,</span></span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-com\">#        它自己不打印业务日志到 stdout——stdio 通道 stdout 会被协议占用。</span></span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\"><span class=\"c-com\">#        审计写 stderr / 文件。下面用 NoneType 占位,实际请从环境读 token)</span></span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\"><span class=\"c-com\"># 验证:  被 code/w11/team_skeleton.py 通过 MCPClient 接入并 list_tools</span></span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\"><span class=\"c-kw\">import</span> os</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\"><span class=\"c-kw\">import</span> time</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\"><span class=\"c-kw\">from</span> mcp.server.fastmcp <span class=\"c-kw\">import</span> FastMCP  <span class=\"c-com\"># uv pip install mcp</span></span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">mcp = FastMCP(<span class=\"c-str\">&quot;research-mcp&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\"><span class=\"c-com\"># 鉴权 token(生产从密钥管理读,别硬编码)</span></span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">API_TOKEN = os.environ.get(<span class=\"c-str\">&quot;MCP_TOKEN&quot;</span>, <span class=\"c-str\">&quot;dev-token&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\"><span class=\"c-com\"># 假知识库(教学用;真实场景接 RAG/数据库)</span></span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">KB = {</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">    <span class=\"c-str\">&quot;agent&quot;</span>: <span class=\"c-str\">&quot;Agent 是能感知环境、自主决策、调用工具行动的智能体。&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">    <span class=\"c-str\">&quot;react&quot;</span>: <span class=\"c-str\">&quot;ReAct 是推理(Reasoning)与行动(Act)交替的 Agent 范式。&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">    <span class=\"c-str\">&quot;mcp&quot;</span>: <span class=\"c-str\">&quot;MCP 是 Model Context Protocol,标准化工具/资源的发现与调用。&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">}</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _audit(tool: str, args: dict, ok: bool, result: str) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;调用审计:记谁/何时/调什么/结果。生产落库,此处写 stderr。&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">    <span class=\"c-kw\">import</span> sys</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">    line = (</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">        f<span class=\"c-str\">&quot;[AUDIT] ts={time.time():.0f} tool={tool} args={args} &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">        f<span class=\"c-str\">&quot;ok={ok} res_len={len(result)}\\n&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">    sys.stderr.write(line)  <span class=\"c-com\"># 注意:stdout 被 MCP 协议占用,审计走 stderr</span></span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">    sys.stderr.flush()</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _auth(token: str | <span class=\"c-kw\">None</span>) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> token == API_TOKEN</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">@mcp.tool()</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\"><span class=\"c-kw\">def</span> search_kb(query: str, token: str = <span class=\"c-str\">&quot;&quot;</span>) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;在本地知识库搜索。</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">    Args:</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">        query: 搜索关键词(如 agent/react/mcp)。</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">        token: 调用凭证。</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> _auth(token):</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">        _audit(<span class=\"c-str\">&quot;search_kb&quot;</span>, {<span class=\"c-str\">&quot;query&quot;</span>: query}, <span class=\"c-kw\">False</span>, <span class=\"c-str\">&quot;unauthorized&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-str\">&quot;ERROR: unauthorized&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">    hits = [v <span class=\"c-kw\">for</span> k, v <span class=\"c-kw\">in</span> KB.items() <span class=\"c-kw\">if</span> query.lower() <span class=\"c-kw\">in</span> k]</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">    result = hits[0] <span class=\"c-kw\">if</span> hits <span class=\"c-kw\">else</span> f<span class=\"c-str\">&quot;未找到关于 {query} 的资料&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">    _audit(<span class=\"c-str\">&quot;search_kb&quot;</span>, {<span class=\"c-str\">&quot;query&quot;</span>: query}, <span class=\"c-kw\">True</span>, result)</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> result</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">@mcp.tool()</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\"><span class=\"c-kw\">def</span> fetch_url(url: str, token: str = <span class=\"c-str\">&quot;&quot;</span>) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;抓取网页正文(带超时,拦危险 url)。</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">    Args:</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">        url: 要抓取的网址。</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">        token: 调用凭证。</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> _auth(token):</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">        _audit(<span class=\"c-str\">&quot;fetch_url&quot;</span>, {<span class=\"c-str\">&quot;url&quot;</span>: url}, <span class=\"c-kw\">False</span>, <span class=\"c-str\">&quot;unauthorized&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-str\">&quot;ERROR: unauthorized&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">    <span class=\"c-com\"># 简易沙箱:拦截内网/本地/文件协议(防 SSRF/读本地文件)</span></span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> any(b <span class=\"c-kw\">in</span> url <span class=\"c-kw\">for</span> b <span class=\"c-kw\">in</span> (<span class=\"c-str\">&quot;file://&quot;</span>, <span class=\"c-str\">&quot;127.0.0.1&quot;</span>, <span class=\"c-str\">&quot;localhost&quot;</span>, <span class=\"c-str\">&quot;169.254&quot;</span>, <span class=\"c-str\">&quot;::1&quot;</span>)):</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">        _audit(<span class=\"c-str\">&quot;fetch_url&quot;</span>, {<span class=\"c-str\">&quot;url&quot;</span>: url}, <span class=\"c-kw\">False</span>, <span class=\"c-str\">&quot;blocked&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-str\">&quot;ERROR: blocked dangerous url&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">    <span class=\"c-com\"># 生产用 httpx + readability 抽正文,带超时。此处 mock</span></span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">    result = f<span class=\"c-str\">&quot;（模拟抓取 {url} 的正文内容……）&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\">    _audit(<span class=\"c-str\">&quot;fetch_url&quot;</span>, {<span class=\"c-str\">&quot;url&quot;</span>: url}, <span class=\"c-kw\">True</span>, result)</span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> result</span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\"><span class=\"c-kw\">if</span> __name__ == <span class=\"c-str\">&quot;__main__&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">    <span class=\"c-com\"># stdio 传输:被 MCPClient(StdioMCPConfig) 拉起</span></span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">    mcp.run(transport=<span class=\"c-str\">&quot;stdio&quot;</span>)</span></div>\n</div>", "lines": 86, "explanation": "server.py 是本教程的可运行示例代码，示范对应周次核心概念；顶部注释含运行前置依赖与预期输出，建议结合左侧源码与对应周文档「动手作业」一起读。", "knowledge_points": [], "related_docs": ["W11-多Agent协作平台实战(上)"]};
